    const x = cv.getContext('2d'); x.clearRect(0, 0, 700, 120); contrib.forEach((v, k) => { x.fillStyle = v > 0 ? 'rgba(28,126,214,' + (0.25 + 0.7 * v) + ')' : '#f1f3f5'; x.fillRect(10 + k * 6.7, 90 - v * 70, 5.5, Math.max(2, v * 70)); }); txt(x, '0', 10, 108, '#868e96', 10); txt(x, '1', 680, 108, '#868e96', 10); txt(x, 'התרומה של כל אחת מ־101 רמות הרגישות', 350, 112, '#495057', 11, 'center'); const zero = contrib.filter(v => v === 0).length;
