    if (hov) { const cx = (Math.floor(hov[0] / st) + 0.5) * st, cy = (Math.floor(hov[1] / st) + 0.5) * st; const rf = [36, 90, 220][lv]; x.strokeStyle = '#fff'; x.lineWidth = 2; x.setLineDash([5, 4]); x.beginPath(); x.arc(cx * s, cy * s, rf * s, 0, 7); x.stroke(); x.setLineDash([]); x.fillStyle = '#fab005'; x.fillRect((cx - st / 2) * s, (cy - st / 2) * s, st * s, st * s); }
