      x.strokeStyle = '#868e96'; x.lineWidth = 1.5; x.beginPath(); x.moveTo(ax0, ay0 + ah); x.lineTo(ax0 + aw, ay0 + ah - 80 / 160 * ah); x.stroke(); txt(x, 'L1 (בקנה מידה, זהה לשניהם)', ax0 + aw - 4, ay0 + ah - 92, '#868e96', 10, 'right'); x.lineWidth = 1;
