    const R = runMethod(fr, keys[m]); R.dets.forEach(d => sb(x, [T(d.box[0]), TY(d.box[1]), T(d.box[2]), TY(d.box[3])], d.partial ? '#e03131' : CCOL[d.cls], 2, d.partial ? [3, 2] : []));
    if (m) tiles(BW, BH, 640, 0.2).forEach(([tx, ty]) => { x.strokeStyle = 'rgba(255,255,255,.4)'; x.setLineDash([6, 4]); x.strokeRect(T(tx), TY(ty), 640 * s, 640 * s); x.setLineDash([]); });
