    const f = thermalField(h, 360, 203); putGray(cT, toGray(f, 5, 45), 360, 203, iron);
    const y = cg.getContext('2d'); y.clearRect(0, 0, 720, 180); const X = t => 50 + t / 24 * 640, Yv = v => 160 - (v - 0) / 60 * 145; y.strokeStyle = '#dee2e6'; y.strokeRect(50, 15, 640, 145); for (let t = 0; t <= 24; t += 3) txt(y, t + ':00', X(t), 175, '#868e96', 10, 'center'); [0, 20, 40, 60].forEach(v => txt(y, v + '°', 44, Yv(v) + 4, '#868e96', 10, 'right'));
    [['person', '#e03131', 'אדם'], ['grass', '#2f9e44', 'דשא'], ['asphalt', '#495057', 'אספלט'], ['walk', '#adb5bd', 'מדרכה']].forEach(([k, c, n], q) => { y.strokeStyle = c; y.lineWidth = 2.2; y.beginPath(); for (let t = 0; t <= 24; t += 0.25) { const p = [X(t), Yv(temps(t)[k])]; t ? y.lineTo(p[0], p[1]) : y.moveTo(p[0], p[1]); } y.stroke(); txt(y, n, 684, 28 + q * 13, c, 10, 'right', true); }); y.lineWidth = 1;
    const cross = []; for (let t = 0; t < 24; t += 0.05) { ['grass', 'walk'].forEach(k => { const a = temps(t)[k] - temps(t).person, b = temps(t + 0.05)[k] - temps(t).person; if (a * b <= 0) cross.push([t, k]); }); } cross.forEach(([t, k]) => { y.fillStyle = 'rgba(250,176,5,.35)'; y.fillRect(X(t) - 6, 15, 12, 145); }); y.strokeStyle = '#212529'; y.setLineDash([4, 3]); y.beginPath(); y.moveTo(X(h), 15); y.lineTo(X(h), 160); y.stroke(); y.setLineDash([]);
    const T = temps(h); const dG = T.person - T.grass, dW = T.person - T.walk; const vis = Math.min(Math.abs(dG), Math.abs(dW)); const fmt = t => String(Math.floor(t)).padStart(2, '0') + ':' + String(Math.round((t % 1) * 60)).padStart(2, '0');
